VALUES
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 164, 'school-164', 'Texas A&M International University (TAMIU)', '未連絡・公開情報整理（2026.11.28）', $rep_164${"id":"school-164","name":"Texas A&M International University (TAMIU)","slug":"school-164","order":164,"article":"<article class=\"sheet generated\" id=\"school-164\" data-crm-id=\"164\" data-school-id=\"164\" data-updated=\"2026-11-28\" style=\"--navy:#500000;--blue:#500000;--spirit:#8C1D40;--pale:color-mix(in srgb,#500000 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Texas A&amp;M International University (TAMIU)</h2><div class=\"jp-title\">テキサスA&amp;Mインターナショナル大学</div><div class=\"meta-row\"><span>NCAA D2</span><span>Lone Star</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Dustdevils ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・Lone StarのDustdevils。</b></p><div class=\"stat-line\"><b>5勝 8敗 3分</b><span>2026年・11月28日確認時点<br>リーグ 2勝6敗2分 <a href=\"https://godustdevils.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">Lone Star 2勝6敗2分（総合5勝8敗3分）。Laredo本拠で、少数精鋭ロースターながら強豪揃いのリーグ戦で競り合いを演じた。</p><p class=\"team-facilities\">ホームは学内のDustdevil Soccer Field。Kinesiology Convocation Building等をトレーニング拠点とする。屋内ウエイト施設・グラウンドの公式写真は未取得。 <a href=\"https://godustdevils.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>Dustdevil Soccer Field｜<a href=\"https://godustdevils.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Texas · Laredo</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>テキサス州南部ラレド（国境都市）の公立大学。キャンパス内のResidential Learning CommunityやUniversity Village等があり、学内寮・アパート型の住居環境を備える。</p><p><span class=\"topic-label\">住居と条件</span>州立で留学生比率が高く、Competitive Scholarship Waiver（奨学金取得による州内学費適用）運用実績がある点は総費用圧縮の大きな材料。冬期・夏期の滞在条件や通学・生活環境は別途確認。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>ラレド市内はEl Metro路線バス網があるが、空港移動や遠征時は車・大学手配が中心。詳細路線・最寄停留所は別途確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／州立総合大学</td></tr><tr><th scope=\"row\">学生数</th><td><b>約6,600〜6,700人（学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>非居住外国人比率・教員比：公式詳細確認待ち</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>A.R. Sanchez, Jr. School of BusinessのMarketing BBAが候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB（ビジネス）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>約$48,000〜$51,000（大学公開レンジ参考・卒業後数年） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD（TX Waiver適用前）</div><p class=\"cost-scope\">2026–27大学公表COA参考・州外・学内居住（秋春各15単位）。奨学金・TX Waiver控除なし。</p><table class=\"cost-table\"><tr><td>州外学費・必須費（30単位想定）</td><td>$24,534</td></tr><tr><td>住居（学内標準）</td><td>$6,480</td></tr><tr><td>食事（ミールプラン標準）</td><td>$3,850</td></tr><tr><td>教材・用品</td><td>$1,280</td></tr><tr><td>交通＋個人費</td><td>$2,798</td></tr><tr><td>留学生医療保険・国際費</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>確認額小計（保険別）</td><td>$38,942</td></tr></table><p class=\"note\">州外学費・必須費$24,534、標準住居$6,480＋食事$3,850、教材・交通・個人費$4,078の合算。TX州Competitive Scholarship Waiver適用時は州内学費水準（約$9,496前後）まで圧縮余地あり。留学生医療保険・国際学生費・夏期滞在・渡航費は別途未確定。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>住居$6,480・食事$3,850は学内標準予算。テキサス州外の学生・留学生でも所定以上の競技/学業奨学金を得ると州内学費換算となるWaiver制度の対象校。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Claudio Arias</strong><span>HC / Head Coach</span><a href=\"mailto:carias@tamiu.edu\">carias@tamiu.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Roberto Hernandez</strong><span>Associate HC（AC枠）</span><a href=\"mailto:roberto.hernandez@tamiu.edu\">roberto.hernandez@tamiu.edu</a></div></div></div><p class=\"note\">他AC: Alex Buttery（alex.buttery@tamiu.edu）。HC Claudio Ariasは21年以上の長期指揮。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総29名・最上級2人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>1名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>0名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>0名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>1名</strong></span></div></div><p>2026公式ロスター掲載29人（少数精鋭）で、最上級生は計2人と非常に若い編成。最上級DFはHeiko Drömer（Sr.）1名、Junior DFもYannick Papenhagen 1名のみ（他Sophomore Jorge Delgado等が主力）。上級生が少なく、即戦力DF/SBの編入枠・出場機会を打診しやすい構成。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://godustdevils.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/tamiu_msoccer/\" target=\"_blank\" rel=\"noopener\">公式Instagram @tamiu_msoccer ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Texas A&amp;M International University (TAMIU)</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-164\"><summary>Texas A&amp;M International University (TAMIU)｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://godustdevils.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://godustdevils.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://godustdevils.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.tamiu.edu/financialaid/cost-of-attendance.shtml\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://godustdevils.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/tamiu_msoccer/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@tamiu_msoccer）</a></li></ul></details>","division":"NCAA D2","region_code":"tx"}$rep_164$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 165, 'school-165', 'University of Texas at Dallas (UT Dallas)', '未連絡・公開情報整理（2026.11.28）', $rep_165${"id":"school-165","name":"University of Texas at Dallas (UT Dallas)","slug":"school-165","order":165,"article":"<article class=\"sheet generated\" id=\"school-165\" data-crm-id=\"165\" data-school-id=\"165\" data-updated=\"2026-11-28\" style=\"--navy:#154734;--blue:#154734;--spirit:#E87500;--pale:color-mix(in srgb,#154734 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>University of Texas at Dallas (UT Dallas)</h2><div class=\"jp-title\">テキサス大学ダラス校</div><div class=\"meta-row\"><span>NCAA D2</span><span>Lone Star</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Comets ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・Lone StarのComets。</b></p><div class=\"stat-line\"><b>11勝 2敗 7分</b><span>2026年・11月28日確認時点<br>リーグ 4勝1敗5分 <a href=\"https://utdcomets.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">11勝2敗7分（勝率.725）・リーグ4勝1敗5分（勝率.650）の上位好成績。ホーム6勝1敗2分・アウェイ5勝1敗5分と安定感が高く、D3からD2移行後すぐ上位で戦える競技力を示した。</p><p class=\"team-facilities\">ホームは照明・観客席・電子表示を備えたUTD Soccer Complex。学内にはActivity CenterやAthletic Performance Centerも整備。屋内施設・グラウンドの公式写真は未取得。 <a href=\"https://utdcomets.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>UTD Soccer Complex｜<a href=\"https://utdcomets.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Texas · Richardson</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>ダラス近郊リチャードソンに位置する研究型州立大。学内にUniversity Commons寮やUniversity Villageアパート群など充実した住居が整備されている。</p><p><span class=\"topic-label\">住居と条件</span>DFW都市圏内で生活利便性が高く、学業評価も高い。UT System規定によりF-1/J-1留学生はUT SHIP医療保険加入が原則必須（承認免除制度あり）。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>ダラス都市圏のDARTライトレール／バス（UT Dallas駅・Comet Cruiserシャトル等）によるアクセス環境あり。詳細は大学案内要確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／研究型大学</td></tr><tr><th scope=\"row\">学生数</th><td><b>約21,700人以上（学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>卒業率約74%（Scorecard参考）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>Naveen Jindal School of Management（JSOM）のMarketing BSが候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB（ビジネス・会計）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>約$76,400（大学全体指標・DFW就労圏で高水準） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD（TX Waiver適用前）</div><p class=\"cost-scope\">2026–27州外学部（12単位以上・秋春）・学内居住＋UT SHIP留学生医療保険（夏含む年額）。奨学金・Waiver控除なし。</p><table class=\"cost-table\"><tr><td>州外学費・必須費（基本）</td><td>$40,250</td></tr><tr><td>住居（学内標準）</td><td>$9,570</td></tr><tr><td>食事（ミールプラン標準）</td><td>$5,038</td></tr><tr><td>教材・交通・個人費（参考）</td><td>$5,200</td></tr><tr><td>UT SHIP留学生保険（年額）</td><td>$3,707</td></tr><tr class=\"total\"><td>州外参考小計＋留学生保険</td><td>$63,765</td></tr></table><p class=\"note\">州外基本学費・必須費約$40,250（Variable/GuaranteedやBusiness学部+$60/単位の加算で変動）に住居・食事$14,608、教材・交通・個人費参考$5,200、UT SHIP 2026–27年額$3,707（秋$1,554＋春$1,534＋夏$619）を加算。TX Waiver適用時は大きく圧縮余地あり。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>州外定価は高めだが、Competitive Scholarship Waiver対象校。高いGPA（3.29）を活かした学業評価とWaiver併用の可否をコーチ・入学窓口に要確認。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Jason Hirsch</strong><span>HC / Head Coach</span><a href=\"mailto:jason.hirsch@utdallas.edu\">jason.hirsch@utdallas.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Jude Anuwe</strong><span>AC / Assistant Coach</span><a href=\"mailto:jude.anuwe@utdallas.edu\">jude.anuwe@utdallas.edu</a></div></div></div><p class=\"note\">HC Jason Hirschは2013年より指揮。Volunteer ACとしてJack Peel、Kevin Whiteが在籍。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総36名・最上級8人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>4名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>1名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>2名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>1名</strong></span></div></div><p>2026公式ロスター掲載36人、最上級生8人。最上級DFは4名（Josh Zemanski[D/M], Julio De Los Reyes, Tabor Robinson[D/M], Tim Mietenkorte[Gr.]）が在籍し卒業見込み。Junior DFは3名（Tyler Leonard, Owen Lagerwey[D/M], Yannis Benae）で、上級DFの入れ替わりに伴う競争枠を確認したい。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://utdcomets.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/utdallasmsoc/\" target=\"_blank\" rel=\"noopener\">公式Instagram @utdallasmsoc ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ University of Texas at Dallas (UT Dallas)</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-165\"><summary>University of Texas at Dallas (UT Dallas)｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://utdcomets.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://utdcomets.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://utdcomets.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://finaid.utdallas.edu/\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://utdcomets.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/utdallasmsoc/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@utdallasmsoc）</a></li></ul></details>","division":"NCAA D2","region_code":"tx"}$rep_165$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 166, 'school-166', 'Clayton State University', '未連絡・公開情報整理（2026.11.28）', $rep_166${"id":"school-166","name":"Clayton State University","slug":"school-166","order":166,"article":"<article class=\"sheet generated\" id=\"school-166\" data-crm-id=\"166\" data-school-id=\"166\" data-updated=\"2026-11-28\" style=\"--navy:#003366;--blue:#003366;--spirit:#E87722;--pale:color-mix(in srgb,#003366 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Clayton State University</h2><div class=\"jp-title\">クレイトン州立大学</div><div class=\"meta-row\"><span>NCAA D2</span><span>Peach Belt</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Lakers ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・Peach BeltのLakers。</b></p><div class=\"stat-line\"><b>7勝 5敗 7分</b><span>2026年・11月28日確認時点<br>リーグ 4勝3敗5分 <a href=\"https://claytonstatesports.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">7勝5敗7分・リーグ4勝3敗5分と勝ち越し・引き分けが多く接戦に強いシーズン。18人の新戦力と上級生コアを融合させた。</p><p class=\"team-facilities\">ホームは照明・観客席を備えた天然芝のLaker Field（約500人収容＋隣接練習場）。Athletics Center内にウエイト室・トレーニング室を完備。公式写真は未取得。 <a href=\"https://claytonstatesports.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>Laker Field｜<a href=\"https://claytonstatesports.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Georgia · Morrow</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>アトランタ都市圏南部モローの州立大学。学内にLaker Hall・Laker Villageの学生住居があり、都市圏近接ながら生活コストが比較的抑えやすい環境。</p><p><span class=\"topic-label\">住居と条件</span>Georgia州立大学システム（USG）に属し、州外学費自体が比較的安価な設定。留学生はUSGの必須健康保険制度の対象（年額は大学窓口で別途確認）。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>アトランタ都市圏（Hartsfield-Jackson国際空港まで近距離）に位置し、MARTA・地域バスとの接続可否は大学案内で確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／州立大学</td></tr><tr><th scope=\"row\">学生数</th><td><b>約4,300〜4,400人（学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>中規模キャンパス（USG傘下）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>College of BusinessのMarketing BBA（Digital Marketing等）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB（ビジネス）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>Scorecard掲載（卒業後進路詳細は公式ページ参照） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD</div><p class=\"cost-scope\">2026–27大学公表COA・州外・学内居住（秋春）。奨学金控除なし。</p><table class=\"cost-table\"><tr><td>州外学費</td><td>$20,400</td></tr><tr><td>必須費</td><td>$1,116</td></tr><tr><td>住居（学内）</td><td>$6,816</td></tr><tr><td>食事（学内）</td><td>$5,410</td></tr><tr><td>教材1,250＋個人4,405＋交通1,385</td><td>$7,040</td></tr><tr><td>USG留学生医療保険</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>確認額小計（保険別）</td><td>$40,782</td></tr></table><p class=\"note\">公表COA総額$40,862から連邦ローン費$80を除外。大学システム（USG）の留学生健康保険は別途必須だが2026–27本人年額未確認のため小計外。渡航・夏期費用も別。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>州外学費＋必須費が約$21,516、学内住食が$12,226と比較的低く、少額の奨学金でも総自己負担を抑えやすい価格帯。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Pete Petersen</strong><span>HC / Head Coach</span><a href=\"mailto:PetePetersen@Clayton.edu\">PetePetersen@Clayton.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Jonny Evans</strong><span>AC / Assistant Coach</span><span>メール公式未掲載</span></div></div></div><p class=\"note\">HC Pete Petersenは2004年就任。他AC（Miguel Torrecillas / Bryce Billington等）を含め、AC陣の個人メールは公式ディレクトリ未掲載（キャンパスディレクトリはLochID認証内のみ）。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総29名・最上級8人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>1名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>3名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>3名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>1名</strong></span></div></div><p>2026公式ロスター掲載29人、最上級生8人（うちMF 3・FW 3が卒業見込みで攻撃陣・中盤の入れ替えが多い）。最上級DFはSonny Simpson 1名、Junior DFはAgustin Bezara 1名とDFの上級生は少人数であり、サイドバック／ウイング兼任枠の需要を確認する価値がある。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://claytonstatesports.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/csulakersmsoc/\" target=\"_blank\" rel=\"noopener\">公式Instagram @csulakersmsoc ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Clayton State University</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-166\"><summary>Clayton State University｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://claytonstatesports.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://claytonstatesports.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://claytonstatesports.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.clayton.edu/financial-aid/cost-of-attendance\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://claytonstatesports.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/csulakersmsoc/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@csulakersmsoc）</a></li></ul></details>","division":"NCAA D2","region_code":"other_public"}$rep_166$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 167, 'school-167', 'University of North Georgia', '未連絡・公開情報整理（2026.11.28）', $rep_167${"id":"school-167","name":"University of North Georgia","slug":"school-167","order":167,"article":"<article class=\"sheet generated\" id=\"school-167\" data-crm-id=\"167\" data-school-id=\"167\" data-updated=\"2026-11-28\" style=\"--navy:#003087;--blue:#003087;--spirit:#B9975B;--pale:color-mix(in srgb,#003087 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>University of North Georgia</h2><div class=\"jp-title\">ノースジョージア大学</div><div class=\"meta-row\"><span>NCAA D2</span><span>Peach Belt</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Nighthawks ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・Peach BeltのNighthawks。</b></p><div class=\"stat-line\"><b>14勝 4敗 5分</b><span>2026年・11月28日確認時点<br>リーグ 6勝2敗4分 <a href=\"https://ungathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">14勝4敗5分（勝率.717）・リーグ6勝2敗4分。2026年はチーム史上最高の全米2位ランクやNCAA D2トーナメント2回戦進出を達成した強豪。</p><p class=\"team-facilities\">ホームはダロネガのLynn Cottrell Park内UNG Soccer Field（専用のSoccer Field House併設）。屋内ウエイト・グラウンド公式写真は未取得。 <a href=\"https://ungathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>UNG Soccer Field at Lynn Cottrell Park｜<a href=\"https://ungathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Georgia · Dahlonega</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>ジョージア州北部の大学町ダロネガが主キャンパス。伝統的な寮生活と編入単位評価・アドバイジング体制が充実。</p><p><span class=\"topic-label\">住居と条件</span>注意：2026年11月18日にHC Anel Lilic氏の退任が公式発表され、後任または暫定HCは未発表。連絡は現職ACのJoel McIlroy氏等を通じて最新体制を確認してから行うこと。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>ダロネガは山間部の大学町でアトランタ都市圏から車約1時間超。公共交通は限定的のため生活・空港アクセスは事前確認が必要。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／州立大学</td></tr><tr><th scope=\"row\">学生数</th><td><b>約16,100人以上（システム全体学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>ビジネス学部は全体の約27%を占める主力</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>Mike Cottrell College of BusinessのMarketing BBA（Digital Marketing等）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB（ビジネス）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>約$50,135（大学全体指標参考） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD</div><p class=\"cost-scope\">2026–27大学公表COA（Out-of-Country/留学生）・Dahlonega学内居住・秋春。奨学金控除なし。</p><table class=\"cost-table\"><tr><td>留学生学費（Out-of-Country）</td><td>$22,440</td></tr><tr><td>必須費</td><td>$1,180</td></tr><tr><td>住居＋食事（Dahlonega標準）</td><td>$13,900</td></tr><tr><td>教材1,570＋交通1,380＋個人2,680</td><td>$5,630</td></tr><tr><td>USG留学生医療保険</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>確認額小計（保険別）</td><td>$43,150</td></tr></table><p class=\"note\">留学生学費$22,440（国内州外は$21,780）＋必須費$1,180＋住居・食事$13,900＋間接費$5,630。大学システム（USG）の留学生健康保険は別途必須だが年額未確認のため小計外。渡航・夏期費用別。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>Dahlonega学内住居＋食事標準予算は$13,900。USG加盟校で州外・留学生学費水準も比較的抑えめ。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Anel Lilic</strong><span>HC（退任発表・後任未定）</span><span>メール公式未掲載</span></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Joel McIlroy</strong><span>AC / Assistant Coach</span><a href=\"mailto:alexander.mcilroy@ung.edu\">alexander.mcilroy@ung.edu</a></div></div></div><p class=\"note\">他スタッフ：GA Joe Conway（joe.conway@ung.edu）、GA Mauricio Uribe（メール未掲載）。新HC決定状況を確認してからアプローチする。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総30名・最上級9人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>2名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>3名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>3名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>1名</strong></span></div></div><p>2026公式ロスター掲載30人、最上級生9人。最上級DFはRohan Blackwell（Sr.）とMax Garnett（Gr.）の2名、Junior DFは6名（Owen Wallace, Bryan Benoit, Dominik Kosut, Sebastian Kristensen, Andres Galicia, Cameron Pfahl）と守備層の競争は厚いが、攻撃・中盤を含め9名が最上級。新体制の補強方針を要確認。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://ungathletics.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/ung_msoccer/\" target=\"_blank\" rel=\"noopener\">公式Instagram @ung_msoccer ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ University of North Georgia</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-167\"><summary>University of North Georgia｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://ungathletics.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://ungathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://ungathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://ung.edu/financial-aid/cost-of-attendance.php\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://ungathletics.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/ung_msoccer/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@ung_msoccer）</a></li></ul></details>","division":"NCAA D2","region_code":"other_public"}$rep_167$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 168, 'school-168', 'Sul Ross State University', '未連絡・公開情報整理（2026.11.28）', $rep_168${"id":"school-168","name":"Sul Ross State University","slug":"school-168","order":168,"article":"<article class=\"sheet generated\" id=\"school-168\" data-crm-id=\"168\" data-school-id=\"168\" data-updated=\"2026-11-28\" style=\"--navy:#A6192E;--blue:#A6192E;--spirit:#1F2937;--pale:color-mix(in srgb,#A6192E 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Sul Ross State University</h2><div class=\"jp-title\">スル・ロス州立大学</div><div class=\"meta-row\"><span>NCAA D2</span><span>Lone Star</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Lobos ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・Lone StarのLobos。</b></p><div class=\"stat-line\"><b>0勝 16敗 0分</b><span>2026年・11月28日確認時点<br>リーグ 0勝10敗0分 <a href=\"https://srlobos.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">0勝16敗0分・リーグ0勝10敗0分と再建期。2026年5月にGerry Cleary新HCが就任し、D3からD2移行後のチーム立て直しを図っている段階。</p><p class=\"team-facilities\">ホームはアルパインのLobo Soccer Field（2015年建設・2023年改修）。屋内ウエイト施設・グラウンドの公式写真は未取得。 <a href=\"https://srlobos.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>Lobo Soccer Field｜<a href=\"https://srlobos.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Texas · Alpine</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>西テキサス・ビッグベンド地域の大学町アルパインにある小規模州立大学（学部約1,300〜1,400人）。主にキャンパス内の学生寮で生活する環境。</p><p><span class=\"topic-label\">住居と条件</span>テキサス州のCompetitive Scholarship Waiver対象校で、出場機会と総費用最小化を両立しやすい候補。2026-11時点で公式ディレクトリにAC掲載なし。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>アルパインは遠隔の小都市（最寄り主要空港はMidland/OdessaやEl Paso）。移動手段・寮の長期休暇対応は要確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／小規模州立大学</td></tr><tr><th scope=\"row\">学生数</th><td><b>約1,300〜1,400人（Alpine学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>公開指標は少人数キャンパス（卒業率約30%）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>Business Administration（一般ビジネス／マーケティング関連履修）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB認証は未確認（一般ビジネス学位）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>約$40,400〜$47,300（Scorecard参考レンジ） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD（TX Waiver適用前）</div><p class=\"cost-scope\">非居住者・年30単位・Alpine学内居住の公式参考レンジ下限ベース。奨学金・TX Waiver控除なし。</p><table class=\"cost-table\"><tr><td>州外学費・必須費（30単位下限）</td><td>$21,880</td></tr><tr><td>住居＋食事（学内下限参考）</td><td>$10,892</td></tr><tr><td>教材790＋交通2,263＋個人3,630</td><td>$6,683</td></tr><tr><td>留学生医療保険</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>参考小計（保険別）</td><td>$39,455</td></tr></table><p class=\"note\">公式掲載の非居住者学費・必須費レンジ（$21,880–$23,060）と住食（$10,892–$11,556）等の下限参考値を使用。TX Competitive Scholarship Waiver適用時は大幅圧縮余地あり。留学生健康保険は別途加入必須（年額変動）。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>アルパインの住居・食費水準が低く、競技奨学金＋TX Waiverが成立すれば年間総負担を大幅に抑えられる可能性がある。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Gerry Cleary</strong><span>HC / Head Coach</span><a href=\"mailto:gcleary@sulross.edu\">gcleary@sulross.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Current staff — verify</strong><span>AC枠（公式未掲載）</span><span>メール公式未掲載</span></div></div></div><p class=\"note\">Gerry Cleary氏は2026年5月5日就任。公式Staff Directory（srlobos.com）にAC/GAの掲載はなく、2026–27のGA募集求人あり。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総25名・最上級2人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>2名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>0名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>0名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>0名</strong></span></div></div><p>2026公式ロスター掲載25人とコンパクトで、最上級生はDF 2名（Christian Martinez, Marlon Meda）のみ、Junior DFもRomain Bricier 1名。全敗からの再建期であり、2027年に即戦力として試合に出られる枠が最も見込みやすい構成。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://srlobos.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/lobosoccersrsu/\" target=\"_blank\" rel=\"noopener\">公式Instagram @lobosoccersrsu ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Sul Ross State University</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-168\"><summary>Sul Ross State University｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://srlobos.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://srlobos.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://srlobos.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.sulross.edu/financial-aid/cost-of-attendance/\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://srlobos.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/lobosoccersrsu/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@lobosoccersrsu）</a></li></ul></details>","division":"NCAA D2","region_code":"tx"}$rep_168$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 169, 'school-169', 'Auburn University at Montgomery (AUM)', '未連絡・公開情報整理（2026.11.28）', $rep_169${"id":"school-169","name":"Auburn University at Montgomery (AUM)","slug":"school-169","order":169,"article":"<article class=\"sheet generated\" id=\"school-169\" data-crm-id=\"169\" data-school-id=\"169\" data-updated=\"2026-11-28\" style=\"--navy:#E86100;--blue:#E86100;--spirit:#111827;--pale:color-mix(in srgb,#E86100 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Auburn University at Montgomery (AUM)</h2><div class=\"jp-title\">オーバーン大学モンゴメリー校</div><div class=\"meta-row\"><span>NCAA D2</span><span>Gulf South</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Warhawks ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・Gulf SouthのWarhawks。</b></p><div class=\"stat-line\"><b>11勝 4敗 3分</b><span>2026年・11月28日確認時点<br>リーグ 7勝1敗2分 <a href=\"https://aumathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">11勝4敗3分（勝率.694）・リーグ7勝1敗2分（勝率.800）。2026年は全米ランク最高4位（最終18位近辺）に入り、NCAA D2南地区トーナメントにも出場した強豪。</p><p class=\"team-facilities\">ホームは学内のAUM Soccer Stadium（AUM Athletics Complex内）。Student-Athlete Performance Centerも整備。公式写真は未取得。 <a href=\"https://aumathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>AUM Soccer Stadium｜<a href=\"https://aumathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Alabama · Montgomery</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>アラバマ州都モンゴメリーの州立大学。学内にWarhawk Hall等の学生寮・アパート型住居を備え、都市生活とキャンパスの利便性を両立。</p><p><span class=\"topic-label\">住居と条件</span>F-1/J-1留学生は大学指定SHIP保険（BCBS Alabama / AHP）への自動加入対象（条件付き免除制度あり）。専攻はAACSB認証のBSBA Marketingが合致。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>モンゴメリー市内バス路線およびモンゴメリー地域空港（MGM）が利用可能（アトランタへも車移動圏）。学内移動・遠征環境は別途確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／州立大学</td></tr><tr><th scope=\"row\">学生数</th><td><b>約2,500〜3,000人（学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>国際選手を含む競争力の高いスポーツ環境</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>College of BusinessのMarketing（BSBA）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB（ビジネス）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>約$42,600〜$42,900（大学全体指標参考） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD</div><p class=\"cost-scope\">2026–27非居住者フルタイム（各学期13単位想定・秋春）・学内標準＋SHIP留学生保険。奨学金控除なし。</p><table class=\"cost-table\"><tr><td>州外学費・必須費</td><td>$24,406</td></tr><tr><td>住居＋食事（COA標準予算）</td><td>$19,368</td></tr><tr><td>教材2,500＋交通3,625＋個人1,890</td><td>$8,015</td></tr><tr><td>留学生医療保険（SHIP年額）</td><td>$2,081</td></tr><tr class=\"total\"><td>州外COA＋留学生保険</td><td>$53,870</td></tr></table><p class=\"note\">非居住者学費・必須費$24,406（$884/単位＋諸費）、住食標準予算$19,368（寮・プラン選択で$7,000–$12,000+帯の実費選択も可）、教材・交通・個人費$8,015に2026–27 SHIP保険参考$2,081（秋$826.5＋春$820.8＋夏$433.2）を加算。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>COA上の住食予算は$19,368と高めだが、実際の学内寮・食事プランの組み合わせで実費を大きく下げられる場合があり契約別確認が必要。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Matthew Thorne</strong><span>HC / Head Coach</span><a href=\"mailto:mthorne@aum.edu\">mthorne@aum.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Joshua Davies</strong><span>AC / Assistant Coach</span><a href=\"mailto:jdavies@aum.edu\">jdavies@aum.edu</a></div></div></div><p class=\"note\">Joshua Davies氏は2026年シーズン前に加入したAC。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総34名・最上級10人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>5名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>1名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>3名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>1名</strong></span></div></div><p>2026公式ロスター掲載34人、最上級生10人。特に最上級DFが5名（Alan De Paula, Thomas Pain, Ryan McQueen, Nathan Aupied[Gr.], Braden Nye）と非常に多く、守備ラインの主力（All-GSCのAlan De Paula含む）が一斉に卒業見込み。Junior DFも3名（Luke Hammons, Luke Butcher, Ty Powell）おり、2027年のDF補強需要が明確に期待できる。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://aumathletics.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/aumwarhawksmsoc/\" target=\"_blank\" rel=\"noopener\">公式Instagram @aumwarhawksmsoc ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Auburn University at Montgomery (AUM)</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-169\"><summary>Auburn University at Montgomery (AUM)｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://aumathletics.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://aumathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://aumathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.aum.edu/tuition-and-fees/\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://aumathletics.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/aumwarhawksmsoc/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@aumwarhawksmsoc）</a></li></ul></details>","division":"NCAA D2","region_code":"other_public"}$rep_169$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 170, 'school-170', 'Slippery Rock University', '未連絡・公開情報整理（2026.11.28）', $rep_170${"id":"school-170","name":"Slippery Rock University","slug":"school-170","order":170,"article":"<article class=\"sheet generated\" id=\"school-170\" data-crm-id=\"170\" data-school-id=\"170\" data-updated=\"2026-11-28\" style=\"--navy:#006747;--blue:#006747;--spirit:#1E3A2F;--pale:color-mix(in srgb,#006747 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Slippery Rock University</h2><div class=\"jp-title\">スリッパリーロック大学</div><div class=\"meta-row\"><span>NCAA D2</span><span>PSAC</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"The Rock ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・PSACのThe Rock。</b></p><div class=\"stat-line\"><b>5勝 6敗 7分</b><span>2026年・11月28日確認時点<br>リーグ 3勝3敗4分 <a href=\"https://rockathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">5勝6敗7分・リーグ3勝3敗4分。引き分け7試合と接戦を粘り強く戦い抜いた（Daemenに7–1大勝など得点爆発力も持つ）。</p><p class=\"team-facilities\">ホームはJames Egli Field（大試合・キャンプ等はMihalik-Thompson Stadium、屋内はMorrow Field Houseも活用）。公式写真は未取得。 <a href=\"https://rockathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>James Egli Field｜<a href=\"https://rockathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Pennsylvania · Slippery Rock</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>ペンシルベニア州西部（ピッツバーグ北約1時間）のPASSHE州立大学。学内寮（Studio SuiteやTraditional Hall）の評価が高く、Harcumと同州で単位移行しやすい。</p><p><span class=\"topic-label\">住居と条件</span>留学生向けの特別減額学費枠（$12,504＋必須費$3,271）があり、GPA 3.0以上の州外生授業料減免制度とあわせてコスト優位性が高い。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>ピッツバーグ近郊の大学町。学内シャトルや地域交通はあるが遠距離移動（PIT空港等）の手段は事前確認が必要。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／州立大学（PASSHE）</td></tr><tr><th scope=\"row\">学生数</th><td><b>約6,500〜6,800人（学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>卒業率約66〜68%（Scorecard参考）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>School of BusinessのBSBA（Marketing専攻／実務・ケース演習重視）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>AACSB（ビジネス）</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>Scorecard掲載（卒業後進路詳細は公式ページ参照） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD（留学生基準）</div><p class=\"cost-scope\">2026–27留学生向けI-20財務証明項目ベース・学内平均住食。奨学金控除なし。</p><table class=\"cost-table\"><tr><td>留学生学費（特別単価）</td><td>$12,504</td></tr><tr><td>必須費</td><td>$3,271</td></tr><tr><td>住居＋食事（学内平均）</td><td>$10,900</td></tr><tr><td>教材1,700＋個人1,500＋預託金80</td><td>$3,280</td></tr><tr><td>留学生医療保険</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>留学生基準小計（保険別）</td><td>$29,955</td></tr></table><p class=\"note\">留学生特別学費$12,504＋必須費$3,271＋平均住食$10,900＋教材・個人・初回デポジット$3,280（公式I-20合算目安は$27,765と表記、内訳合算と差あり）。通常州外学費・必須費は$20,015（GPA3.0以上減免で$15,847）。健康保険・渡航費別。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>通常州外でもGPA 3.0以上で授業料減免対象となり、さらに留学生向け特別学費設定が低額なため年間$20,000前後の自己負担が現実的に狙える。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Kevin Wilhelm</strong><span>HC / Head Coach</span><a href=\"mailto:kevin.wilhelm@sru.edu\">kevin.wilhelm@sru.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Iain Langstone</strong><span>AC / Assistant Coach</span><a href=\"mailto:iain.langstone@sru.edu\">iain.langstone@sru.edu</a></div></div></div><p class=\"note\">他スタッフ：GA Jack Smith（メール未掲載）。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総27名・最上級6人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>3名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>1名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>2名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>0名</strong></span></div></div><p>2026公式ロスター掲載27人、最上級生6人。最上級DFは3名（Dylan Greggs[5th], Gabin Lonjard[Sr.], Patrick Tierney[Sr.]）で主力の抜ける割合が高い一方、Junior DFはPlamedi Warsinsky 1名のみ。編入DF・SBの即戦力需要が極めて期待しやすいロスター構成。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://rockathletics.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/srumsoccer/\" target=\"_blank\" rel=\"noopener\">公式Instagram @srumsoccer ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Slippery Rock University</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-170\"><summary>Slippery Rock University｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://rockathletics.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://rockathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://rockathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.sru.edu/admissions/tuition-and-fees\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://rockathletics.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/srumsoccer/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@srumsoccer）</a></li></ul></details>","division":"NCAA D2","region_code":"east"}$rep_170$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 171, 'school-171', 'Commonwealth University - Bloomsburg', '未連絡・公開情報整理（2026.11.28）', $rep_171${"id":"school-171","name":"Commonwealth University - Bloomsburg","slug":"school-171","order":171,"article":"<article class=\"sheet generated\" id=\"school-171\" data-crm-id=\"171\" data-school-id=\"171\" data-updated=\"2026-11-28\" style=\"--navy:#6F263D;--blue:#6F263D;--spirit:#C5A028;--pale:color-mix(in srgb,#6F263D 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Commonwealth University - Bloomsburg</h2><div class=\"jp-title\">コモンウェルス大学ブルームズバーグ校</div><div class=\"meta-row\"><span>NCAA D2</span><span>PSAC</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Huskies ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・PSACのHuskies。</b></p><div class=\"stat-line\"><b>6勝 7敗 5分</b><span>2026年・11月28日確認時点<br>リーグ 2勝5敗3分 <a href=\"https://bloomsburgathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">6勝7敗5分・リーグ2勝5敗3分。ホームでは6勝1敗2分と非常に強かった一方、アウェイで0勝6敗3分と明暗が分かれた。</p><p class=\"team-facilities\">ホームはSteph Pettit Stadium。屋内施設としてNelson Field House等を利用。公式写真は未取得。 <a href=\"https://bloomsburgathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>Steph Pettit Stadium｜<a href=\"https://bloomsburgathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Pennsylvania · Bloomsburg</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>ペンシルベニア州中央部ブルームズバーグのPASSHE州立大学（統合Commonwealth Universityの一校）。Harcumと同州で単位互換性が高い。</p><p><span class=\"topic-label\">住居と条件</span>学内にTraditional・Suite・Apartment型の寮が整備（原則2年次までの学内居住要件あり）。留学生医療保険条件は別途確認。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>PA州中央部の大学町でフィラデルフィア／Harcum圏から車約2時間半〜3時間。公共交通は長距離バス中心で要事前確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／州立大学（PASSHE）</td></tr><tr><th scope=\"row\">学生数</th><td><b>約10,000人規模（ブルームズバーグ拠点参考）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>PASSHE統合による高い単位互換性</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>Business Administration（BSBA・Marketing／Managementモジュール）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>統合後のAACSB等認証は現行ディレクトリ要確認</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>Scorecard掲載（卒業後進路詳細は公式ページ参照） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD</div><p class=\"cost-scope\">2026–27 Commonwealth Univ.公表・州外・学内居住COA（秋春）。奨学金控除なし。</p><table class=\"cost-table\"><tr><td>州外学費</td><td>$19,986</td></tr><tr><td>必須費</td><td>$4,238</td></tr><tr><td>住居（学内標準）</td><td>$8,618</td></tr><tr><td>食事（学内標準）</td><td>$3,250</td></tr><tr><td>教材1,200＋個人2,000＋交通1,540</td><td>$4,740</td></tr><tr><td>留学生医療保険</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>確認額小計（保険別）</td><td>$40,832</td></tr></table><p class=\"note\">公表COAから連邦ローン費$78を除外。学費$19,986＋必須費$4,238＋住居$8,618＋食事$3,250＋教材・個人・交通$4,740。2年次まで学内居住要件あり。留学生保険・渡航費・夏期は別途。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>PASSHEシステム統合によりHarcum（PA州）からの単位認定・編入移行を進めやすい。州外学費＋必須費は約$24,224。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Mark Bassett</strong><span>HC / Head Coach</span><a href=\"mailto:mbassett@bloomu.edu\">mbassett@bloomu.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Nick Passaniti</strong><span>GA（AC枠）</span><a href=\"mailto:stgamsoc@bloomu.edu\">stgamsoc@bloomu.edu</a></div></div></div><p class=\"note\">Volunteer ACにThomas Iskra、Liam Harmon（いずれもメール未掲載）がいるため、AC枠は公式メールのあるGA Nick Passanitiを登録。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総44名・最上級4人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>0名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>2名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>2名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>0名</strong></span></div></div><p>2026公式ロスター掲載44人と大所帯で、下級生中心の編成（最上級生4人：MF 2・FW 2、最上級DFは0人）。Junior DFが6名（Ty Mikula, Gage Haniwalt, Owen Peri, Logan Savage, Conner Fedorko, Arthur Tavares）在籍しているため、DF枠の競争は激しい点は留意。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://bloomsburgathletics.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/buhuskiesmsoc/\" target=\"_blank\" rel=\"noopener\">公式Instagram @buhuskiesmsoc ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Commonwealth University - Bloomsburg</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-171\"><summary>Commonwealth University - Bloomsburg｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://bloomsburgathletics.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://bloomsburgathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://bloomsburgathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.commonwealthu.edu/tuition-and-aid/cost-attendance\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://bloomsburgathletics.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/buhuskiesmsoc/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@buhuskiesmsoc）</a></li></ul></details>","division":"NCAA D2","region_code":"east"}$rep_171$::jsonb, 1),
('47e7c1a9-a806-4f65-b5ed-2b9b124ef337'::uuid, 172, 'school-172', 'Commonwealth University - Lock Haven', '未連絡・公開情報整理（2026.11.28）', $rep_172${"id":"school-172","name":"Commonwealth University - Lock Haven","slug":"school-172","order":172,"article":"<article class=\"sheet generated\" id=\"school-172\" data-crm-id=\"172\" data-school-id=\"172\" data-updated=\"2026-11-28\" style=\"--navy:#862633;--blue:#862633;--spirit:#374151;--pale:color-mix(in srgb,#862633 7%,white)\"><header class=\"sheet-head\"><div class=\"school-titles\"><h2>Commonwealth University - Lock Haven</h2><div class=\"jp-title\">コモンウェルス大学ロックヘイブン校</div><div class=\"meta-row\"><span>NCAA D2</span><span>PSAC</span></div></div><img class=\"school-logo\" style=\"background:white;padding:4px;border-radius:4px\" src=\"data:image/svg+xml;base64,\" alt=\"Bald Eagles ロゴ\"></header><section class=\"section overview01\"><h3><span class=\"num\">01</span> サッカー｜競技成績・チーム・施設</h3><div class=\"overview-grid\"><div class=\"overview-copy\"><p class=\"team-intro\"><b>NCAA D2・PSACのBald Eagles。</b></p><div class=\"stat-line\"><b>6勝 4敗 9分</b><span>2026年・11月28日確認時点<br>リーグ 5勝1敗4分 <a href=\"https://lockhavenathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">公式日程・戦績 ↗</a></span></div><p class=\"team-results\">6勝4敗9分・リーグ5勝1敗4分（勝率.700）とリーグ戦で非常に堅実な強さを発揮。9分と負けにくい守備組織を構築した。</p><p class=\"team-facilities\">試合・練習はFoundation Field、人工芝・照明付きのHubert Jack Stadium、Stern Athletic Complex等を活用。公式写真は未取得。 <a href=\"https://lockhavenathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式施設案内 ↗</a></p></div><div class=\"overview-visuals\"><div class=\"gallery campus-photos verified-photos\"><figure class=\"campus-shot facility\" data-photo-role=\"indoor\"><div class=\"photo-missing\">確認出来ず</div><figcaption>屋内ウエイト施設｜公式写真未確認</figcaption></figure><figure class=\"campus-shot stadium\" data-photo-role=\"ground\"><div class=\"photo-missing\">確認出来ず</div><figcaption>Hubert Jack Stadium / Foundation Field｜<a href=\"https://lockhavenathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">公式案内 ↗</a></figcaption></figure></div><aside class=\"mini-location\"><div><h4>Pennsylvania · Lock Haven</h4><p>位置・詳細はCRM地図参照</p></div></aside></div></div></section><div class=\"two-col life-academics\"><section class=\"section\"><h3><span class=\"num\">02</span> 寮と暮らし｜街・住居</h3><p><span class=\"topic-label\">住む場所と街の特徴</span>ペンシルベニア州中央部ロックヘイブンの小規模PASSHE州立キャンパス（学部約2,100〜2,500人）。伝統寮・Suite・学内アパートで1,000人以上収容。</p><p><span class=\"topic-label\">住居と条件</span>Bloomsburgと同じCommonwealth Universityシステムに属し、Harcum（PA州）からの単位互換性・学費水準の面で有利。留学生医療保険は別途確認。</p><p><span class=\"topic-label\">公共交通・都市へのアクセス</span>PA州中央部の小都市（州都ハリスバーグやステートカレッジ近郊）。長距離移動手段は車または地域バスを事前確認。</p></section><section class=\"section academics03\"><style>\n.sheet .academic-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:12px;line-height:1.4;margin:0 0 3px;overflow-wrap:anywhere}\n.sheet .academic-table th,.sheet .academic-table td{padding:1px 3px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}\n.sheet .academic-table th[scope=row]{width:72px;white-space:nowrap;overflow-wrap:normal;word-break:keep-all;background:var(--pale);color:var(--navy);font-weight:750}\n.sheet .academic-table .academic-group th{background:var(--navy);color:white;font-size:11px;font-weight:800;padding:1px 4px;border-bottom:1px solid white}\n.sheet .academic-table td b{font-weight:800}\n@media print{.sheet.generated .academic-table{font-size:10px;line-height:1.3}.sheet:not(.generated) .academic-table{font-size:11px;line-height:1.3}}\n</style><h3><span class=\"num\">03</span> 学校と学びの特徴｜卒業後の進路</h3><table class=\"academic-table\" aria-label=\"学校と学び・卒業後の進路\"><colgroup><col style=\"width:72px\"><col></colgroup><tbody><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">基本情報</th></tr><tr><th scope=\"row\">学校区分</th><td>公立／小規模州立大学（PASSHE）</td></tr><tr><th scope=\"row\">学生数</th><td><b>約2,100〜2,500人（学部）</b></td></tr><tr><th scope=\"row\">規模・構成</th><td>少人数環境・PASSHE単位互換性高</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">専攻と学び</th></tr><tr><th scope=\"row\">学位・分野</th><td>Business Administration（BSBA・Marketing／Managementモジュール）が候補。</td></tr><tr><th scope=\"row\">専門認証</th><td>統合後のAACSB等認証は現行ディレクトリ要確認</td></tr><tr class=\"academic-group\"><th colspan=\"2\" scope=\"colgroup\">卒業後の進路</th></tr><tr><th scope=\"row\">卒業後指標</th><td>Scorecard掲載（卒業後進路詳細は公式ページ参照） <a href=\"https://collegescorecard.ed.gov/\" target=\"_blank\" rel=\"noopener\">米教育省 ↗</a></td></tr></tbody></table><p class=\"note\">指標：公開データ・公式大学情報（2026/11確認）。専攻・留学生限定値ではない。</p></section></div><div class=\"two-col lower-report\"><section class=\"section costs04\"><h3><span class=\"num\">04</span> 費用｜年間総額・学費・寮費・保険</h3><div class=\"cost-block\"><div class=\"cost-caption\">奨学金なし・年間USD</div><p class=\"cost-scope\">2026–27 Commonwealth Univ.公表・州外・学内居住COA（秋春）。奨学金控除なし。</p><table class=\"cost-table\"><tr><td>州外学費</td><td>$19,986</td></tr><tr><td>必須費</td><td>$4,238</td></tr><tr><td>住居（学内標準）</td><td>$8,618</td></tr><tr><td>食事（学内標準）</td><td>$3,250</td></tr><tr><td>教材1,200＋個人2,000＋交通1,540</td><td>$4,740</td></tr><tr><td>留学生医療保険</td><td>年額未確認・別途</td></tr><tr class=\"total\"><td>確認額小計（保険別）</td><td>$40,832</td></tr></table><p class=\"note\">公表COAから連邦ローン費$78を除外（Bloomsburgと同システム共通単価ベース、寮タイプにより微差あり）。学費$19,986＋必須費$4,238＋住居$8,618＋食事$3,250＋間接費$4,740。留学生保険・渡航費・夏期は別途。</p></div><div class=\"meal-note\"><b>住居・奨学金・保険の補足：</b>PA州立システム（PASSHE）共通の州外学費枠で、単位移行ロスの少なさとコスト抑制を両立しやすい。</div></section><div class=\"right-stack\"><section class=\"section coaches05\"><h3><span class=\"num\">05</span> コーチ｜指導スタッフ・連絡先</h3><div class=\"staff-pair\"><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Patrick Long</strong><span>HC / Head Coach</span><a href=\"mailto:pdl347@lockhaven.edu\">pdl347@lockhaven.edu</a></div></div><div class=\"staff\"><div class=\"staff-photo-missing\">確認出来ず</div><div><strong>Rocco Birns</strong><span>GA / Graduate Assistant</span><span>メール公式未掲載</span></div></div></div><p class=\"note\">HC Patrick Longは2026年で指揮9年目（Lock Haven OB）。GA Rocco Birnsのメールは公式・大学ディレクトリともに未掲載。</p></section><section class=\"section personal06\"><h3><span class=\"num\">06</span> 2026年ロスターと編入への視点</h3><div class=\"roster-summary\"><div class=\"roster-summary-heading\"><b>最上級学年の位置別人数</b><span>2026公式｜総28名・最上級5人</span></div><div class=\"roster-chips\"><span class=\"roster-chip\"><b>DF</b><strong>4名</strong></span><span class=\"roster-chip\"><b>MF</b><strong>1名</strong></span><span class=\"roster-chip\"><b>FW</b><strong>0名</strong></span><span class=\"roster-chip\"><b>GK</b><strong>0名</strong></span></div></div><p>2026公式ロスター掲載28人、最上級生5人のうち実に4人がDF（Kyle Hoyt, Owen Lichtenwalner, Danny Ogan, Scott Manning[D/M]）。Junior DFはAshtyn Skillen 1名のみのため、2027年にかけて守備陣の主力枠が大きく空く見込みで編入先として非常に相性が良い。</p><p class=\"roster-stats\">複数ポジションは最初の表記で1人1区分に集計。2026年11月28日時点の公式ロスター掲載値。DF等の表記から左右のサイド役割は確定できない。</p><p class=\"personal-next\">Senior・Grad・5th等を集計した卒業見込みの参考値。卒業・退団・競技資格終了の確定数ではなく、2027年の補強枠・奨学金・出場機会は未確認。</p></section></div></div><div class=\"link-strip\"><div class=\"qr\"><a href=\"https://lockhavenathletics.com/sports/mens-soccer\" target=\"_blank\" rel=\"noopener\">男子サッカー公式HP ↗</a></div><div class=\"qr\"><a href=\"https://www.instagram.com/lockhavenmsoc/\" target=\"_blank\" rel=\"noopener\">公式Instagram @lockhavenmsoc ↗</a></div></div><footer class=\"sheet-foot\"><span>暁廣のFall 2027編入検討 ／ 家庭内共有用</span><span>2026.11.28確認 ｜ Commonwealth University - Lock Haven</span></footer></article>","chapter":"uncontacted","sources":"<details class=\"sources\" id=\"sources-school-172\"><summary>Commonwealth University - Lock Haven｜出典・確認事項</summary><p>戦績・選手・スタッフ・費用・Instagramは2026年11月28日確認の公式公開情報を参照。Senior等は卒業の断定ではない。費用は2026–27の比較材料で奨学金・Waiver控除前、2027–28確定請求額ではない。位置別人数は最上級学年（Senior・Grad・5th等）の公式表記を用い、複数ポジションは最初の表記で1人1区分に集計。</p><ul><li><a href=\"https://lockhavenathletics.com/sports/mens-soccer/roster\" target=\"_blank\" rel=\"noopener\">01/06 2026公式ロスター</a></li><li><a href=\"https://lockhavenathletics.com/sports/mens-soccer/schedule/2026\" target=\"_blank\" rel=\"noopener\">01 2026日程・戦績</a></li><li><a href=\"https://lockhavenathletics.com/facilities\" target=\"_blank\" rel=\"noopener\">01 公式施設案内</a></li><li><a href=\"https://www.commonwealthu.edu/tuition-and-aid/cost-attendance\" target=\"_blank\" rel=\"noopener\">04 2026–27公式費用・COA</a></li><li><a href=\"https://lockhavenathletics.com/sports/mens-soccer/coaches\" target=\"_blank\" rel=\"noopener\">05 公式コーチスタッフ</a></li><li><a href=\"https://www.instagram.com/lockhavenmsoc/\" target=\"_blank\" rel=\"noopener\">男子サッカー公式Instagram（@lockhavenmsoc）</a></li></ul></details>","division":"NCAA D2","region_code":"east"}$rep_172$::jsonb, 1)
